use rusqlite::{params, Connection};
use tauri::AppHandle;

fn database(app: &AppHandle) -> Result<Connection, String> { let connection = crate::storage::open_database(app)?; connection.execute("CREATE TABLE IF NOT EXISTS ncm_downloads (song_id INTEGER PRIMARY KEY, file_path TEXT, downloaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)", []).map_err(|e| e.to_string())?; Ok(connection) }
pub fn record_download(app: &AppHandle, id: i64, path: Option<&str>) -> Result<(), String> { database(app)?.execute("INSERT INTO ncm_downloads (song_id, file_path) VALUES (?1, ?2) ON CONFLICT(song_id) DO UPDATE SET file_path = COALESCE(excluded.file_path, ncm_downloads.file_path), downloaded_at = CURRENT_TIMESTAMP", params![id, path]).map_err(|e| e.to_string())?; Ok(()) }
pub fn list_downloaded(app: &AppHandle) -> Result<Vec<i64>, String> { let connection = database(app)?; let mut statement = connection.prepare("SELECT song_id FROM ncm_downloads").map_err(|e| e.to_string())?; let rows = statement.query_map([], |row| row.get(0)).map_err(|e| e.to_string())?; let ids = rows.collect::<Result<Vec<i64>, _>>().map_err(|e| e.to_string())?; Ok(ids) }
pub fn mark_downloaded_many(app: &AppHandle, ids: Vec<i64>) -> Result<(), String> { if ids.is_empty() { return Ok(()); } let mut connection = database(app)?; let tx = connection.transaction().map_err(|e| e.to_string())?; { let mut statement = tx.prepare("INSERT INTO ncm_downloads (song_id, file_path) VALUES (?1, ?2) ON CONFLICT(song_id) DO UPDATE SET file_path = COALESCE(excluded.file_path, ncm_downloads.file_path), downloaded_at = CURRENT_TIMESTAMP").map_err(|e| e.to_string())?; for id in &ids { statement.execute(params![id, Option::<String>::None]).map_err(|e| e.to_string())?; } } tx.commit().map_err(|e| e.to_string())?; Ok(()) }
